	local _bit32_bxor = (bit32 and bit32.bxor) or function(a, b)
		local xorVal = 0
		local p = 1
		while a > 0 or b > 0 do
			local ab = a % 2
			local bb = b % 2
			if ab ~= bb then xorVal = xorVal + p end
			a = math.floor(a / 2)
			b = math.floor(b / 2)
			p = p * 2
		end
		return xorVal
	end

	local _OUT_CHUNKS = {}
	local _OUT_CHUNKS_TOP = 0
	local _KEY_STATE = {}
	for i = 1, #_MASTER_KEY do _KEY_STATE[i] = _MASTER_KEY[i] end

	local _RUNNING = true
	local _BLOCK_IDX = 1
	local _BYTE_COUNTER = 0

	-- Control-Flow Flattened Interpreter Loop
	while _RUNNING do
		if _VM_STATE == 0x5A1F then
			-- OP_INIT: Verify state and prime keystream
			if _BLOCK_IDX <= #_STREAM then
				_VM_STATE = 0xB27E
			else
				_VM_STATE = 0xF841
			end
		elseif _VM_STATE == 0xB27E then
			-- OP_STREAM_DECODE: Process base64 quadruplets into dynamic decrypted bytes
			local rawBlock = _STREAM[_BLOCK_IDX]
			local blockLen = #rawBlock
			local charIdx = 1
			local tempOut = {}
			local tempTop = 0

			while charIdx <= blockLen do
				local c1 = _LOOKUP[_byte(rawBlock, charIdx)] or 0
				local c2 = _LOOKUP[_byte(rawBlock, charIdx + 1)] or 0
				local c3 = _LOOKUP[_byte(rawBlock, charIdx + 2)] or 0
				local c4 = _LOOKUP[_byte(rawBlock, charIdx + 3)] or 0
				charIdx = charIdx + 4

				local n = (c1 * 262144) + (c2 * 4096) + (c3 * 64) + c4
				local b1 = math.floor(n / 65536) % 256
				local b2 = math.floor(n / 256) % 256
				local b3 = n % 256

				local tBytes = { b1, b2, b3 }
				for bi = 1, 3 do
					_BYTE_COUNTER = _BYTE_COUNTER + 1
					if _BYTE_COUNTER <= _ORIG_LEN then
						local enc = tBytes[bi]
						local kIdx = ((_BYTE_COUNTER - 1) % 32) + 1
						local kVal = _KEY_STATE[kIdx]
						local sub = _bit32_bxor(enc, kVal)
						local origByte = _INV_SBOX[sub + 1] or 0

						tempTop = tempTop + 1
						tempOut[tempTop] = _char(origByte)

						_KEY_STATE[kIdx] = (kVal + enc + ((_BYTE_COUNTER - 1) % 128)) % 256
					end
				end
			end

			_OUT_CHUNKS_TOP = _OUT_CHUNKS_TOP + 1
			_OUT_CHUNKS[_OUT_CHUNKS_TOP] = _table.concat(tempOut)
			_BLOCK_IDX = _BLOCK_IDX + 1
			_VM_STATE = 0x5A1F
		elseif _VM_STATE == 0xF841 then
			-- OP_EXECUTE_SECURE: Reassemble payload, install zero-console sandbox and execute
			_RUNNING = false
			local fullPayload = _table.concat(_OUT_CHUNKS)
			_OUT_CHUNKS = nil
			_STREAM = nil
			_INV_SBOX = nil
			_MASTER_KEY = nil

			local execFunc, compileErr = _loadstring(fullPayload, "@SonHub_Coach")
			if not execFunc then
				return nil
			end

			return execFunc(...)
		else
			_RUNNING = false
		end
	end
end)(...)
